(1092049, 132950, 30124, '<td valign="top">Nice shot of the forest, too bad the challenge requires a person in there, I''d like the image better without.</td>', 'Nice shot of the forest, too bad the challenge requires a person in there, I''d like the image better without.', '2005-01-05 02:39:25.000000', NULL, 1),
(1092050, 132534, 22479, '<td valign="top">Excellent night time exposure! Just love the pose of the silhouette. This is one of my favorites and I hope it performs well. 10</td>', 'Excellent night time exposure! Just love the pose of the silhouette. This is one of my favorites and I hope it performs well. 10', '2005-01-05 02:40:37.000000', NULL, 1),
(1092052, 133102, 22479, '<td valign="top">Your creativity is inspiring. :-) I think this fits the challenge perfectly and the execution is flawless. This better ribbon or else! 10</td>', 'Your creativity is inspiring. :-) I think this fits the challenge perfectly and the execution is flawless. This better ribbon or else! 10', '2005-01-05 02:42:24.000000', NULL, 1),
(1092058, 132908, 22479, '<td valign="top">Wonderful exposure...I like how the light filters softly between the trees. You have a marvelous eye and this should be in the forefront. 10</td>', 'Wonderful exposure...I like how the light filters softly between the trees. You have a marvelous eye and this should be in the forefront. 10', '2005-01-05 02:44:24.000000', NULL, 1),
