(1092062, 133471, 22479, '<td valign="top">Lovely low-key exposure and wonderful DOF. You did a remarkable job in capturing the snow. Perfect for this challenge. Well done!</td>', 'Lovely low-key exposure and wonderful DOF. You did a remarkable job in capturing the snow. Perfect for this challenge. Well done!', '2005-01-05 02:47:10.000000', NULL, 1),
