(1092066, 132269, 22479, '<td valign="top">This scenery is lush with details. The netting adds to the tropical appeal and entry is aptly titled. Overall a strong entry.</td>', 'This scenery is lush with details. The netting adds to the tropical appeal and entry is aptly titled. Overall a strong entry.', '2005-01-05 02:48:48.000000', NULL, 1),
