(1092073, 133169, 22479, '<td valign="top">Wonderful detail and tonal range. Excellent play of light and shadow filtering between the leaves and branches. <br/> <br/>Image sharpened a tad bit too much evidenced by the aliasing in the leaves and tree trunks. Otherwise stunning and a strong entry.</td>', 'Wonderful detail and tonal range. Excellent play of light and shadow filtering between the leaves and branches.  Image sharpened a tad bit too much evidenced by the aliasing in the leaves and tree trunks. Otherwise stunning and a strong entry.', '2005-01-05 02:50:55.000000', NULL, 1),
(1092074, 133473, 31403, '<td valign="top">outstanding colors.  very striking.  nice image.</td>', 'outstanding colors.  very striking.  nice image.', '2005-01-05 02:51:25.000000', NULL, 1),
(1092076, 132067, 22479, '<td valign="top">Love the detail in the branches and the contrast of the sunlight filtering within. Strong entry.</td>', 'Love the detail in the branches and the contrast of the sunlight filtering within. Strong entry.', '2005-01-05 02:51:32.000000', NULL, 1),
(1092078, 132426, 22479, '<td valign="top">Breathtaking moment. The tonal range is excellent and the exposure perfect. Very strong entry.</td>', 'Breathtaking moment. The tonal range is excellent and the exposure perfect. Very strong entry.', '2005-01-05 02:53:13.000000', NULL, 1),
(1092080, 133342, 22479, '<td valign="top">Wonderful color on the wavy water. Good choice of positioning Waldo, blends right in. :-) <br/> <br/>Very strong entry and the only suggestion I can make for improvement is that I think this entry would be more appealing if you had completely cropped everything above the level of the water, or perhaps leave just a hint of the horizon.</td>', 'Wonderful color on the wavy water. Good choice of positioning Waldo, blends right in. :-)  Very strong entry and the only suggestion I can make for improvement is that I think this entry would be more appealing if you had completely cropped everything above the level of the water, or perhaps leave just a hint of the horizon.', '2005-01-05 02:57:00.000000', NULL, 1),
(1092082, 132252, 22479, '<td valign="top">Lovely soft focus, gives it a nostalgic, rustic feel, and good job in hiding Waldo. :-)<br/></td>', 'Lovely soft focus, gives it a nostalgic, rustic feel, and good job in hiding Waldo. :-)', '2005-01-05 02:58:08.000000', NULL, 1),
