(1093288, 133379, 4210, '<td valign="top">I love the curved wall, but the way the pier looks makes the photofeel unlevel, even if it isn''t.</td>', 'I love the curved wall, but the way the pier looks makes the photofeel unlevel, even if it isn''t.', '2005-01-05 15:57:56.000000', NULL, 1),
(1093289, 133311, 4210, '<td valign="top">Looks unlevel, blocky, and doesn''t use the rule of thirds, which likely would have benefited this photo. Lighting is also poor.</td>', 'Looks unlevel, blocky, and doesn''t use the rule of thirds, which likely would have benefited this photo. Lighting is also poor.', '2005-01-05 15:58:57.000000', NULL, 1),
(1093321, 132252, 28548, '<td valign="top">took me a sec.. nice. I like the Idea.</td>', 'took me a sec.. nice. I like the Idea.', '2005-01-05 16:22:14.000000', NULL, 1),
(1093331, 132346, 27845, '<td valign="top">Nice composition. The border is too big though. The green and black would have done well if the black one would have been thinner.<br/>You slightly missed the challenge. There was only one person supposed to be in the picture. 6.</td>', 'Nice composition. The border is too big though. The green and black would have done well if the black one would have been thinner.You slightly missed the challenge. There was only one person supposed to be in the picture. 6.', '2005-01-05 16:26:24.000000', NULL, 1),
(1093332, 133053, 28548, '<td valign="top">looks like a statue.. I like it.<br/></td>', 'looks like a statue.. I like it.', '2005-01-05 16:26:26.000000', NULL, 1),
(1093334, 133408, 27845, '<td valign="top">Cool. A bit too orange. Have you tried it in b&amp;w? 5.</td>', 'Cool. A bit too orange. Have you tried it in b&w? 5.', '2005-01-05 16:27:00.000000', NULL, 1),
(1093340, 133471, 18349, '<td valign="top">The top half of the pic is VERY dark on this monitor except for the flakes. The bottom half shows fairly good detail in the house, the grass, and the low branches of the tree. It is overall dark though.  I wonder if it is a calibration issue.  Good composition and I can see what you were after.  :o)</td>', 'The top half of the pic is VERY dark on this monitor except for the flakes. The bottom half shows fairly good detail in the house, the grass, and the low branches of the tree. It is overall dark though.  I wonder if it is a calibration issue.  Good composition and I can see what you were after.  :o)', '2005-01-05 16:29:27.000000', NULL, 1),
(1093343, 132977, 27845, '<td valign="top">I like the leading lines and the perspective. The vanishing point might be a bit father off. You might have crouched, and taken the shot from further below.<br/>The shadows which come in from the right enhance the path a bit, which is a bit overexposed. It''s hard to get this right in a wood, curves in post processing might have helped here.<br/>By the way, there was only one person supposed to be in the shot. 8, nonetheless :)</td>', 'I like the leading lines and the perspective. The vanishing point might be a bit father off. You might have crouched, and taken the shot from further below.The shadows which come in from the right enhance the path a bit, which is a bit overexposed. It''s hard to get this right in a wood, curves in post processing might have helped here.By the way, there was only one person supposed to be in the shot. 8, nonetheless :)', '2005-01-05 16:29:48.000000', NULL, 1),
(1093347, 133450, 30342, '<td valign="top">Creative.</td>', 'Creative.', '2005-01-05 16:31:42.000000', NULL, 1),
(1093348, 132534, 27845, '<td valign="top">Nice idea. A bit too dark though, you might have placed a light in front of the grass, and a shining moon in the upper right corner would have been perfect. (I know you can''t control the moon, I''m just telling you that there''s an empty space). Nice shadows. Sexy silhouette. 7.</td>', 'Nice idea. A bit too dark though, you might have placed a light in front of the grass, and a shining moon in the upper right corner would have been perfect. (I know you can''t control the moon, I''m just telling you that there''s an empty space). Nice shadows. Sexy silhouette. 7.', '2005-01-05 16:31:52.000000', NULL, 1),
(1093350, 132418, 30342, '<td valign="top">That border is really scaring me.</td>', 'That border is really scaring me.', '2005-01-05 16:32:15.000000', NULL, 1),
(1093353, 133108, 17103, '<td valign="top">If there''s a person here, I can''t find him.... will come back later to look again.<br/> <br/>Hi again!  I received your private message and, of course, now that you point out the light-colored object in the center of the photo, I can see it. lol!  You must have rolled yourself into a ball to appear so small. :)  You''re probably a bit too camouflaged, but it''s a cool shot nonetheless.</td>', 'If there''s a person here, I can''t find him.... will come back later to look again. Hi again!  I received your private message and, of course, now that you point out the light-colored object in the center of the photo, I can see it. lol!  You must have rolled yourself into a ball to appear so small. :)  You''re probably a bit too camouflaged, but it''s a cool shot nonetheless.', '2005-01-05 16:32:28.000000', NULL, 1),
(1093354, 132249, 30342, '<td valign="top">Too funny!</td>', 'Too funny!', '2005-01-05 16:32:36.000000', NULL, 1),
(1093358, 132426, 17103, '<td valign="top">Very well camouflaged but still identifiable.... nice shot!</td>', 'Very well camouflaged but still identifiable.... nice shot!', '2005-01-05 16:33:24.000000', NULL, 1),
(1093360, 131512, 27845, '<td valign="top">Is there someone swimming in the center of the image? I''m not sure wether that''s a head or something else... You might have straightened the image, I don''t like the tilt. There''s no clear distinction between fore- and background. 4.</td>', 'Is there someone swimming in the center of the image? I''m not sure wether that''s a head or something else... You might have straightened the image, I don''t like the tilt. There''s no clear distinction between fore- and background. 4.', '2005-01-05 16:33:47.000000', NULL, 1),
(1093364, 131561, 28548, '<td valign="top">WOW.. This is a beautiful sunset..did a great job.</td>', 'WOW.. This is a beautiful sunset..did a great job.', '2005-01-05 16:35:22.000000', NULL, 1),
(1093365, 131716, 27845, '<td valign="top">This one''s too easy to be interesting. When shoting children, crouch, go down to their eye level, it makes better images. If you wanted to do a shot with your son or someone else in camouflage clothes, you might have considered a wider crop, stepping back from your model to give him a better chance to blend with the background. 3.</td>', 'This one''s too easy to be interesting. When shoting children, crouch, go down to their eye level, it makes better images. If you wanted to do a shot with your son or someone else in camouflage clothes, you might have considered a wider crop, stepping back from your model to give him a better chance to blend with the background. 3.', '2005-01-05 16:35:38.000000', NULL, 1),
(1093367, 132004, 27845, '<td valign="top">Nice reflections. I''m still checking the windows...7.</td>', 'Nice reflections. I''m still checking the windows...7.', '2005-01-05 16:36:16.000000', NULL, 1),
(1093368, 133447, 27845, '<td valign="top">Too much disorder. There''s no real structure. 4.</td>', 'Too much disorder. There''s no real structure. 4.', '2005-01-05 16:36:58.000000', NULL, 1),
(1093369, 131618, 28548, '<td valign="top">I really like this photo..</td>', 'I really like this photo..', '2005-01-05 16:37:44.000000', NULL, 1),
(1093370, 132249, 31602, '<td valign="top">This is very inventive for the Where''s Waldo theme.  I definitely see Waldo</td>', 'This is very inventive for the Where''s Waldo theme.  I definitely see Waldo', '2005-01-05 16:38:04.000000', NULL, 1),
(1093371, 132174, 27845, '<td valign="top">Behind the camera maybe? I can''t find anybody in the picture, but then again, the challenge is about hiding a person. I think there''s someone on the right side, between the trees, but I''m not sure. 5.</td>', 'Behind the camera maybe? I can''t find anybody in the picture, but then again, the challenge is about hiding a person. I think there''s someone on the right side, between the trees, but I''m not sure. 5.', '2005-01-05 16:38:26.000000', NULL, 1),
(1093373, 132291, 28548, '<td valign="top">I see an arm.. but no waldo..</td>', 'I see an arm.. but no waldo..', '2005-01-05 16:39:47.000000', NULL, 1),
(1093375, 133278, 27845, '<td valign="top">Nice idea. You know how to move in the gray area. 7.</td>', 'Nice idea. You know how to move in the gray area. 7.', '2005-01-05 16:40:23.000000', NULL, 1),
(1093377, 132716, 27845, '<td valign="top">This does well as b&amp;w. I lke the reflections. 7.</td>', 'This does well as b&w. I lke the reflections. 7.', '2005-01-05 16:41:06.000000', NULL, 1),
(1093379, 133394, 27845, '<td valign="top">Nice pattern. I''d have set the cow out of the center, that would have provided morr interest to the picture. I can''t find Waldo :( I give you a 6 nonetheless.</td>', 'Nice pattern. I''d have set the cow out of the center, that would have provided morr interest to the picture. I can''t find Waldo :( I give you a 6 nonetheless.', '2005-01-05 16:43:44.000000', NULL, 1),
(1093382, 133357, 27845, '<td valign="top">I like the sharpness. And the car :)<br/>Waldo''s in behind the stairs, right? Nice details, nice contrast, no pitch black areas, nor any blown out ones. I''d have stepped a metre to the right, making the picture more compact. 8.</td>', 'I like the sharpness. And the car :)Waldo''s in behind the stairs, right? Nice details, nice contrast, no pitch black areas, nor any blown out ones. I''d have stepped a metre to the right, making the picture more compact. 8.', '2005-01-05 16:45:55.000000', NULL, 1),
(1093384, 133179, 27845, '<td valign="top">Huh? How can a statue be that big? Did you use a photo of that boy or some special trick? 5.</td>', 'Huh? How can a statue be that big? Did you use a photo of that boy or some special trick? 5.', '2005-01-05 16:47:22.000000', NULL, 1),
(1093386, 132295, 27845, '<td valign="top">Nice title. Good contrast. There are perhaps too many details under the bridge. 7.</td>', 'Nice title. Good contrast. There are perhaps too many details under the bridge. 7.', '2005-01-05 16:49:48.000000', NULL, 1),
(1093387, 133342, 27204, '<td valign="top">Wow...  Took me awhile to find him.</td>', 'Wow...  Took me awhile to find him.', '2005-01-05 16:50:52.000000', NULL, 1),
(1093388, 133214, 27845, '<td valign="top">I think the shadows won...the picture''s too dark. 5.</td>', 'I think the shadows won...the picture''s too dark. 5.', '2005-01-05 16:51:26.000000', NULL, 1),
(1093391, 131512, 30712, '<td valign="top">A good idea for the theme but as a picture I find all the water in the foreground rather plain.</td>', 'A good idea for the theme but as a picture I find all the water in the foreground rather plain.', '2005-01-05 16:52:29.000000', NULL, 1),
(1093392, 131630, 30712, '<td valign="top">Super lighting!</td>', 'Super lighting!', '2005-01-05 16:52:58.000000', NULL, 1),
(1093393, 132313, 27845, '<td valign="top">This one was hard. You could push the contrast a bit and darken the image. 4.</td>', 'This one was hard. You could push the contrast a bit and darken the image. 4.', '2005-01-05 16:53:38.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1093401, 133196, 27845, '<td valign="top">Hm...I believe I know this wood from a former challenge...it''s lovely. THe gigantic trees emphasize the small look of your Waldo. 9.</td>', 'Hm...I believe I know this wood from a former challenge...it''s lovely. THe gigantic trees emphasize the small look of your Waldo. 9.', '2005-01-05 16:57:51.000000', NULL, 1),
(1093405, 132426, 27845, '<td valign="top">Lovely detail. What a cool rock formation. I like the splash of water. Good composition, good choice to desaturate. 10.</td>', 'Lovely detail. What a cool rock formation. I like the splash of water. Good composition, good choice to desaturate. 10.', '2005-01-05 17:00:04.000000', NULL, 1),
(1093407, 133469, 27845, '<td valign="top">You should have fixed the tilted horizon. Nice sunrays. He''s in the small boat in the left, right? 6.</td>', 'You should have fixed the tilted horizon. Nice sunrays. He''s in the small boat in the left, right? 6.', '2005-01-05 17:00:51.000000', NULL, 1),
(1093412, 133278, 27204, '<td valign="top">That''s awesome!  If it would have been a real dalmation it''d be one to hang on the wall.</td>', 'That''s awesome!  If it would have been a real dalmation it''d be one to hang on the wall.', '2005-01-05 17:01:47.000000', NULL, 1),
(1093414, 133193, 30388, '<td valign="top">The picture is really cute, really adorable. Nice idea!</td>', 'The picture is really cute, really adorable. Nice idea!', '2005-01-05 17:02:55.000000', NULL, 1),
(1093417, 133473, 30388, '<td valign="top">Wow, your picture is very beautiful. Nice idea.</td>', 'Wow, your picture is very beautiful. Nice idea.', '2005-01-05 17:03:45.000000', NULL, 1),
(1093421, 132098, 30388, '<td valign="top">Im speechless, this is a very unique picture and I really like that bright red color to it.</td>', 'Im speechless, this is a very unique picture and I really like that bright red color to it.', '2005-01-05 17:04:34.000000', NULL, 1),
