(1095496, 133452, 30313, '<td valign="top">This pretty neat: looks abstract, but then you catch the person''s face, which pulls you back into reality.</td>', 'This pretty neat: looks abstract, but then you catch the person''s face, which pulls you back into reality.', '2005-01-07 02:44:48.000000', NULL, 1),
(1095498, 131546, 30313, '<td valign="top">I like the hand as the focal point for the translucent drape.</td>', 'I like the hand as the focal point for the translucent drape.', '2005-01-07 02:48:31.000000', NULL, 1),
