(1095532, 133152, 30313, '<td valign="top">Don''t like the cropping of the wreath and the car in the lower right is a distraction.  I like the richness of the berries.</td>', 'Don''t like the cropping of the wreath and the car in the lower right is a distraction.  I like the richness of the berries.', '2005-01-07 03:40:03.000000', NULL, 1),
(1095534, 133053, 25890, '<td valign="top">I like the idea and the composition in general. However, the picture looks to me somewhat over-processed (too much tweaking of levels and/or curves maybe?), thus a bit unnatural.</td>', 'I like the idea and the composition in general. However, the picture looks to me somewhat over-processed (too much tweaking of levels and/or curves maybe?), thus a bit unnatural.', '2005-01-07 03:46:51.000000', NULL, 1),
(1095537, 132343, 23478, '<td valign="top">Nice shot.</td>', 'Nice shot.', '2005-01-07 03:57:36.000000', NULL, 1),
(1095542, 131485, 25890, '<td valign="top">The fence is a good example of leading lines. The problem is, it leads the eyes right out of the picture instead of to the point of interest, and the bridge is not strong enough a line to direct the attention back inside from where it converges with the fence. Additionally, the picture suffers from lack of contrast and sharpness, in my opinion.</td>', 'The fence is a good example of leading lines. The problem is, it leads the eyes right out of the picture instead of to the point of interest, and the bridge is not strong enough a line to direct the attention back inside from where it converges with the fence. Additionally, the picture suffers from lack of contrast and sharpness, in my opinion.', '2005-01-07 04:13:41.000000', NULL, 1),
(1095547, 132252, 23478, '<td valign="top">Well now, you almost hid him too well.  Great shot!</td>', 'Well now, you almost hid him too well.  Great shot!', '2005-01-07 04:22:34.000000', NULL, 1),
(1095550, 133085, 23478, '<td valign="top">Interesting shot.  I like the effect.</td>', 'Interesting shot.  I like the effect.', '2005-01-07 04:25:38.000000', NULL, 1),
(1095553, 133179, 23478, '<td valign="top">Great photo!</td>', 'Great photo!', '2005-01-07 04:29:53.000000', NULL, 1),
(1095556, 131428, 23478, '<td valign="top">I like it!</td>', 'I like it!', '2005-01-07 04:33:45.000000', NULL, 1),
(1095561, 132060, 31049, '<td valign="top">I think this photo could have gained a lot if the person would have hidden behind the tree on the right...</td>', 'I think this photo could have gained a lot if the person would have hidden behind the tree on the right...', '2005-01-07 04:41:12.000000', NULL, 1),
(1095562, 133106, 31049, '<td valign="top">Amasing detail you managed to catch in this photo... Was it the top of a tower or just a hill and a powerful zoom lens?</td>', 'Amasing detail you managed to catch in this photo... Was it the top of a tower or just a hill and a powerful zoom lens?', '2005-01-07 04:42:31.000000', NULL, 1),
