INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1095595, 131779, 30712, '<td valign="top">This gives a tremendous feeling of height.</td>', 'This gives a tremendous feeling of height.', '2005-01-07 06:46:42.000000', NULL, 1),
(1095596, 132977, 3306, '<td valign="top">Very nice interpretation of the theme. Your subjects look natural in the picture and not artifically placed to suit the challenge. A nice picture in B &amp; W as well.</td>', 'Very nice interpretation of the theme. Your subjects look natural in the picture and not artifically placed to suit the challenge. A nice picture in B & W as well.', '2005-01-07 06:46:49.000000', NULL, 1),
(1095598, 131956, 30712, '<td valign="top">Best snow scene I''ve seen so far.  Really brilliant and clear.</td>', 'Best snow scene I''ve seen so far.  Really brilliant and clear.', '2005-01-07 06:47:22.000000', NULL, 1),
(1095600, 133152, 30712, '<td valign="top">A gentle tweak to lift the midtones would make this even better.</td>', 'A gentle tweak to lift the midtones would make this even better.', '2005-01-07 06:48:10.000000', NULL, 1),
(1095601, 133169, 3306, '<td valign="top">Wow, you have made this a tough one but I see your little Waldo! Very nice interpretation of the theme. Your Waldo has be included without distracting from the beauty of the picture.</td>', 'Wow, you have made this a tough one but I see your little Waldo! Very nice interpretation of the theme. Your Waldo has be included without distracting from the beauty of the picture.', '2005-01-07 06:48:51.000000', NULL, 1),
(1095603, 131731, 30712, '<td valign="top">Lovely shape and form.</td>', 'Lovely shape and form.', '2005-01-07 06:51:37.000000', NULL, 1),
(1095718, 131561, 25059, '<td valign="top">I love the feel of this shot! I choose this as winner!</td>', 'I love the feel of this shot! I choose this as winner!', '2005-01-07 10:54:02.000000', NULL, 1),
(1095745, 132716, 31443, '<td valign="top">A bit dull but I always like reflections in water so very nice actually</td>', 'A bit dull but I always like reflections in water so very nice actually', '2005-01-07 11:25:48.000000', NULL, 1),
