(1095772, 133053, 19035, '<td valign="top">My number 1 pick to ribbon.  Amazing colors and clarity.  10</td>', 'My number 1 pick to ribbon.  Amazing colors and clarity.  10', '2005-01-07 11:51:38.000000', NULL, 1),
(1095773, 132725, 19035, '<td valign="top">Great title and mood to the picture, almost erie, one of my fav''s.  B &amp; W works well here.</td>', 'Great title and mood to the picture, almost erie, one of my fav''s.  B & W works well here.', '2005-01-07 11:52:16.000000', NULL, 1),
(1095774, 132426, 19035, '<td valign="top">I love the contrasting shades of gray, one of my top picks, I hope you ribbon.  10.</td>', 'I love the contrasting shades of gray, one of my top picks, I hope you ribbon.  10.', '2005-01-07 11:53:14.000000', NULL, 1),
(1095775, 133122, 19035, '<td valign="top">Very creative.  The colors are so vibrant, in my top 5 picks.  A 9 from me.</td>', 'Very creative.  The colors are so vibrant, in my top 5 picks.  A 9 from me.', '2005-01-07 11:54:45.000000', NULL, 1),
(1095776, 133081, 19035, '<td valign="top">Very calming shot.  I wish I could see more of this scene, it is lovely.  8</td>', 'Very calming shot.  I wish I could see more of this scene, it is lovely.  8', '2005-01-07 11:55:29.000000', NULL, 1),
(1095778, 131561, 19035, '<td valign="top">Beautiful range of colors, a great capture.  8</td>', 'Beautiful range of colors, a great capture.  8', '2005-01-07 11:56:03.000000', NULL, 1),
(1095779, 131618, 19035, '<td valign="top">Bumping up to a 9.  Great angle to the picture.  The contrasting light and darks are very striking, meets the challenge dead on.</td>', 'Bumping up to a 9.  Great angle to the picture.  The contrasting light and darks are very striking, meets the challenge dead on.', '2005-01-07 11:57:09.000000', NULL, 1),
(1095781, 131440, 19035, '<td valign="top">This picture made me laugh, very creative.  Good luck.  7.</td>', 'This picture made me laugh, very creative.  Good luck.  7.', '2005-01-07 11:57:41.000000', NULL, 1),
(1095782, 133181, 19035, '<td valign="top">Not thrilled about the frame, but does not affect your score.  I like the sepia, does well here.  Met the challenge dead on.  There is a graininess about this shot that I like very much.  8.</td>', 'Not thrilled about the frame, but does not affect your score.  I like the sepia, does well here.  Met the challenge dead on.  There is a graininess about this shot that I like very much.  8.', '2005-01-07 11:59:40.000000', NULL, 1),
(1095783, 131982, 19035, '<td valign="top">On creativity alone I give you a seven, well done.</td>', 'On creativity alone I give you a seven, well done.', '2005-01-07 12:00:21.000000', NULL, 1),
(1095787, 132534, 24951, '<td valign="top">I find the basketball hoop distracting. I think a good crop to the right, might have put more focus on the window.</td>', 'I find the basketball hoop distracting. I think a good crop to the right, might have put more focus on the window.', '2005-01-07 12:02:20.000000', NULL, 1),
(1095788, 131716, 19035, '<td valign="top">Your picture should be larger and your cute little waldo should be a little more hidden.  He is a cutie.</td>', 'Your picture should be larger and your cute little waldo should be a little more hidden.  He is a cutie.', '2005-01-07 12:02:27.000000', NULL, 1),
(1095795, 132246, 19035, '<td valign="top">This picture has no focal point, while your waldo is there and somewhat hidden, the shot would better withou so much clutter.  I always ask my self would this be a picture I would hang up?  Please dont take my comments too harsh, I am trying to be honest with people to help.  Good luck on future challenges.</td>', 'This picture has no focal point, while your waldo is there and somewhat hidden, the shot would better withou so much clutter.  I always ask my self would this be a picture I would hang up?  Please dont take my comments too harsh, I am trying to be honest with people to help.  Good luck on future challenges.', '2005-01-07 12:05:43.000000', NULL, 1),
(1095801, 133226, 19035, '<td valign="top">There is not enough focus to merit a good score, this has more of a abstract feel to it.</td>', 'There is not enough focus to merit a good score, this has more of a abstract feel to it.', '2005-01-07 12:07:01.000000', NULL, 1),
(1095802, 133406, 19035, '<td valign="top">The colors are very drab and there needs to be more focus.</td>', 'The colors are very drab and there needs to be more focus.', '2005-01-07 12:08:09.000000', NULL, 1),
