INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1096727, 132940, 31214, '<td valign="top">Very original!</td>', 'Very original!', '2005-01-08 03:40:21.000000', NULL, 1),
(1096728, 132534, 31214, '<td valign="top">I like the way you''ve captured the light on the grass</td>', 'I like the way you''ve captured the light on the grass', '2005-01-08 03:41:13.000000', NULL, 1),
(1096730, 133053, 31214, '<td valign="top">Nice job with the colors.  Wish I could take my little roadster here!</td>', 'Nice job with the colors.  Wish I could take my little roadster here!', '2005-01-08 03:43:00.000000', NULL, 1),
(1096731, 132861, 31214, '<td valign="top">Nice "mood" you''ve created.  Too bad there''s a bulb out.  Good job.</td>', 'Nice "mood" you''ve created.  Too bad there''s a bulb out.  Good job.', '2005-01-08 03:44:11.000000', NULL, 1),
(1096732, 133342, 31214, '<td valign="top">Nice colors.</td>', 'Nice colors.', '2005-01-08 03:44:44.000000', NULL, 1),
(1096734, 133354, 31214, '<td valign="top">Love the soft effect you show.</td>', 'Love the soft effect you show.', '2005-01-08 03:46:18.000000', NULL, 1),
(1096736, 132418, 31214, '<td valign="top">Very well hidden!  Good job covering up most of the face.</td>', 'Very well hidden!  Good job covering up most of the face.', '2005-01-08 03:47:22.000000', NULL, 1),
(1096737, 133429, 31214, '<td valign="top">Simple....yet good for the theme.  Funny!</td>', 'Simple....yet good for the theme.  Funny!', '2005-01-08 03:48:13.000000', NULL, 1),
(1096738, 132426, 31214, '<td valign="top">Nicely hidden....looks great in B&amp;W</td>', 'Nicely hidden....looks great in B&W', '2005-01-08 03:49:59.000000', NULL, 1),
(1096740, 131561, 31214, '<td valign="top">Nice sunset.  Is that Waldo''s wife?  Nice peaceful image.</td>', 'Nice sunset.  Is that Waldo''s wife?  Nice peaceful image.', '2005-01-08 03:51:17.000000', NULL, 1),
(1096742, 133044, 31214, '<td valign="top">Congratulations on your ribbon!</td>', 'Congratulations on your ribbon!', '2005-01-08 03:52:41.000000', NULL, 1),
(1096743, 132725, 31214, '<td valign="top">Good job....another crop maybe to hide better</td>', 'Good job....another crop maybe to hide better', '2005-01-08 03:54:48.000000', NULL, 1),
(1096744, 132716, 31214, '<td valign="top">Nice shot.  Here''s my tip...see the white/light on the horizon in the distance.  If your Waldo were back a little further, the white of his shirt would blend with wile/light background and his dark pants would blend with the trees.  Good job though.</td>', 'Nice shot.  Here''s my tip...see the white/light on the horizon in the distance.  If your Waldo were back a little further, the white of his shirt would blend with wile/light background and his dark pants would blend with the trees.  Good job though.', '2005-01-08 03:55:06.000000', NULL, 1),
(1096745, 132641, 31214, '<td valign="top">I like the symetry.</td>', 'I like the symetry.', '2005-01-08 03:59:52.000000', NULL, 1),
(1096747, 132295, 31214, '<td valign="top">Don''t like your title.  Suicide?  Try a broken ankle!</td>', 'Don''t like your title.  Suicide?  Try a broken ankle!', '2005-01-08 04:07:17.000000', NULL, 1),
(1096750, 133180, 31214, '<td valign="top">Nice colors.  Lady is very small!</td>', 'Nice colors.  Lady is very small!', '2005-01-08 04:10:57.000000', NULL, 1),
(1096751, 131718, 31214, '<td valign="top">I like the deep reds!</td>', 'I like the deep reds!', '2005-01-08 04:11:55.000000', NULL, 1),
(1096752, 131716, 31214, '<td valign="top">Are you kidding?</td>', 'Are you kidding?', '2005-01-08 04:16:25.000000', NULL, 1),
(1096773, 132291, 30364, '<td valign="top">Original idea using a Waldo fragment.  8.</td>', 'Original idea using a Waldo fragment.  8.', '2005-01-08 05:00:44.000000', NULL, 1),
(1096774, 131679, 30364, '<td valign="top">Good photo &amp; very clever Waldo; well hidden in full view.  8.</td>', 'Good photo & very clever Waldo; well hidden in full view.  8.', '2005-01-08 05:02:49.000000', NULL, 1),
(1096776, 132940, 30364, '<td valign="top">This is very clever ... 6 for an OK photograph plus 2 because no-one else thought of it = 8</td>', 'This is very clever ... 6 for an OK photograph plus 2 because no-one else thought of it = 8', '2005-01-08 05:05:52.000000', NULL, 1),
(1096778, 133452, 30364, '<td valign="top">Striking shot &amp; very good Waldo.  8.</td>', 'Striking shot & very good Waldo.  8.', '2005-01-08 05:08:00.000000', NULL, 1),
(1096779, 133389, 30364, '<td valign="top">Nice light &amp; perspective, pretty good Waldo.  8.</td>', 'Nice light & perspective, pretty good Waldo.  8.', '2005-01-08 05:09:28.000000', NULL, 1),
(1096782, 132826, 6999, '<td valign="top">I like this - despite a number of things that one ought not to like - the crazy shadow across the horse, the confusion with the horse''s head being in front of the tree; but there''s a certain mad remote quality to it that appeals to me.</td>', 'I like this - despite a number of things that one ought not to like - the crazy shadow across the horse, the confusion with the horse''s head being in front of the tree; but there''s a certain mad remote quality to it that appeals to me.', '2005-01-08 05:13:00.000000', NULL, 1),
(1096785, 133313, 6999, '<td valign="top">The apprach feels a little obvious - though it is well done, and that light ought to add more impact than it actually has. I wonder if a touch more control would be needed, or greater contrast between the lit and ''unlit'' areas - your ''x'' doesn''t register very strongly for me.</td>', 'The apprach feels a little obvious - though it is well done, and that light ought to add more impact than it actually has. I wonder if a touch more control would be needed, or greater contrast between the lit and ''unlit'' areas - your ''x'' doesn''t register very strongly for me.', '2005-01-08 05:15:30.000000', NULL, 1),
(1096788, 132629, 6999, '<td valign="top">This has become rather flat - I don''t get much sense of depth from this lighting - everything''s pretty bright and full on, rather than using a graduation of shading across the set-up.</td>', 'This has become rather flat - I don''t get much sense of depth from this lighting - everything''s pretty bright and full on, rather than using a graduation of shading across the set-up.', '2005-01-08 05:17:34.000000', NULL, 1),
(1096791, 132295, 6999, '<td valign="top">I like your use of compositional techniques to ''hide'' your person; you''ve made a good choice of the ''size'' of that person too. I think it''s perhaps too compex a scene - I mean the buildings, the trees silhouettes, the mud-banks and so on - to score very well here, and also seems to lack that edge of sharp detail.</td>', 'I like your use of compositional techniques to ''hide'' your person; you''ve made a good choice of the ''size'' of that person too. I think it''s perhaps too compex a scene - I mean the buildings, the trees silhouettes, the mud-banks and so on - to score very well here, and also seems to lack that edge of sharp detail.', '2005-01-08 05:31:11.000000', NULL, 1),
(1096794, 131982, 6999, '<td valign="top">The impressionistic and grainy feel of this is pleasing. Composition is strong, sense of the dynamic also strong. There''s a hauntedness to the image - and you''ve kept the detail of the expression on the face well. Nice work.</td>', 'The impressionistic and grainy feel of this is pleasing. Composition is strong, sense of the dynamic also strong. There''s a hauntedness to the image - and you''ve kept the detail of the expression on the face well. Nice work.', '2005-01-08 05:33:24.000000', NULL, 1),
(1096795, 132252, 6999, '<td valign="top">Strong compositional work to hide the figure, and to divert the immediate attention. There''s a certain misted feel to the image, though I wonder if a touch more definition in contrast might have been effective for the voters.</td>', 'Strong compositional work to hide the figure, and to divert the immediate attention. There''s a certain misted feel to the image, though I wonder if a touch more definition in contrast might have been effective for the voters.', '2005-01-08 05:36:50.000000', NULL, 1),
(1096796, 131658, 6999, '<td valign="top">Strong composition, good ''ordinary'' scene, and those graphics add a surprise element. Definitely not the kind of thing that appeals to the wider dpc audience - but it''s a kind of domestic/suburban photography that I like.</td>', 'Strong composition, good ''ordinary'' scene, and those graphics add a surprise element. Definitely not the kind of thing that appeals to the wider dpc audience - but it''s a kind of domestic/suburban photography that I like.', '2005-01-08 05:39:11.000000', NULL, 1),
(1096799, 132313, 6999, '<td valign="top">Too well hidden for my eyes.</td>', 'Too well hidden for my eyes.', '2005-01-08 05:40:21.000000', NULL, 1),
(1096820, 132249, 3306, '<td valign="top">Really good, clever idea. Maybe could have been set up differently to be more interesting. Looks like maybe you were limited in how you could arrange your picture. This is a difficult challenge. Good luck.</td>', 'Really good, clever idea. Maybe could have been set up differently to be more interesting. Looks like maybe you were limited in how you could arrange your picture. This is a difficult challenge. Good luck.', '2005-01-08 06:25:16.000000', NULL, 1),
(1096822, 132426, 3306, '<td valign="top">A very difficult challenge. I have not seen many pictures that  actually incorporate a well done balanced and interesting scene. This picture is one of them. Good job.</td>', 'A very difficult challenge. I have not seen many pictures that  actually incorporate a well done balanced and interesting scene. This picture is one of them. Good job.', '2005-01-08 06:35:05.000000', NULL, 1),
(1096877, 132869, 16488, '<td valign="top">You seem to have missed the challenge topic.<br/>Beautiful scarf and detail on the embroidery.  Your title suggests the boy is the "subject" but he''s too out of focus.  The man with the cane, among other things, creates a distraction in your image making this feel like a snapshot.  Keep trying, you''ll do better next time.</td>', 'You seem to have missed the challenge topic.Beautiful scarf and detail on the embroidery.  Your title suggests the boy is the "subject" but he''s too out of focus.  The man with the cane, among other things, creates a distraction in your image making this feel like a snapshot.  Keep trying, you''ll do better next time.', '2005-01-08 08:38:29.000000', NULL, 1),
(1096878, 133194, 16488, '<td valign="top">The color really carries the mood here.  Simply stated.  Nice.</td>', 'The color really carries the mood here.  Simply stated.  Nice.', '2005-01-08 08:42:30.000000', NULL, 1),
(1096879, 131962, 16488, '<td valign="top">I bet I''m not the only one who can''t find "Waldo" in this picture. ..<br/>Exposure lacks detail in the shadows.  The whole looks almost solarized with an odd color-cast.  A pet peeve of mine is tipped horizons.  The subject had potential, this just didn''t make it for me.</td>', 'I bet I''m not the only one who can''t find "Waldo" in this picture. ..Exposure lacks detail in the shadows.  The whole looks almost solarized with an odd color-cast.  A pet peeve of mine is tipped horizons.  The subject had potential, this just didn''t make it for me.', '2005-01-08 08:47:48.000000', NULL, 1),
(1096880, 133375, 16488, '<td valign="top">Pretty scene.  I think I see "Waldo" on the shore to the far left of the image.  It''s hard to tell because this has lost detail in the shadows--a little too dark for my tastes.  Otherwise it''s lovely: the branches outlined with snow, the shapes building depth through the image, the perfect blacks and whites....</td>', 'Pretty scene.  I think I see "Waldo" on the shore to the far left of the image.  It''s hard to tell because this has lost detail in the shadows--a little too dark for my tastes.  Otherwise it''s lovely: the branches outlined with snow, the shapes building depth through the image, the perfect blacks and whites....', '2005-01-08 08:53:14.000000', NULL, 1),
(1096905, 131440, 14735, '<td valign="top">I would have loved this if you went home got a hat and stud in the front with your back turned, but still a good photo.</td>', 'I would have loved this if you went home got a hat and stud in the front with your back turned, but still a good photo.', '2005-01-08 09:50:35.000000', NULL, 1),
