(1103065, 132426, 19708, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by ipbandara:</b></div><hr/><i>If possible post the colour photo also of this.</i></td></tr></table> <br/>Poof and Thanks!<br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=135610" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/19708/thumb/135610.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/19708/thumb/135610.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/19708/thumb/135610.jpg"/></a> <br/> (resized only)<br/><br/><i>Message edited by author 2005-01-12 02:26:14.</i></td>', 'Originally posted by ipbandara:If possible post the colour photo also of this. Poof and Thanks!  (resized only)', '2005-01-12 02:25:23.000000', '2005-01-12 02:26:14.000000', 0),
