(1547509, 133380, 28261, '<td valign="top">I like the art and the hand.  It however leads me to wonder if this art was a flooring, and the child/baby crawling through the pattern (shot from above or a high angle) what effect it would have.  It would be somewhat surreal.</td>', 'I like the art and the hand.  It however leads me to wonder if this art was a flooring, and the child/baby crawling through the pattern (shot from above or a high angle) what effect it would have.  It would be somewhat surreal.', '2005-07-19 20:19:19.000000', NULL, 0),
(1586460, 132258, 22734, '<td valign="top">This is an outstanding entry for a first try at a challenge. Congartulations and keep reading that manual as most of the secrets are there. Practice, practice and soon you will be on your way.</td>', 'This is an outstanding entry for a first try at a challenge. Congartulations and keep reading that manual as most of the secrets are there. Practice, practice and soon you will be on your way.', '2005-08-04 11:45:48.000000', NULL, 0),
(1777578, 133268, 19831, '<td valign="top">Well, yeah, he''s a little obvious :-), but this is a really cool photo on it''s own. I really like the colors, and the shapes and lines. And the person adds a lot of interest to an already cool image, IMO. Nice job.</td>', 'Well, yeah, he''s a little obvious :-), but this is a really cool photo on it''s own. I really like the colors, and the shapes and lines. And the person adds a lot of interest to an already cool image, IMO. Nice job.', '2005-10-11 21:29:03.000000', NULL, 0),
